class Stream { constructor(protected buf: Buffer) {} }

class FileStream extends Stream {
  readonly #payload: Buffer;
  constructor(fd: number) {
    const buf = makeBuffer(fd);   // before super(): no `this` yet
    super(buf);                   // the dependent "base" gets the payload
    this.#payload = buf;          // field assigned after super returns
  }
}
